Ext.define('BNK.view.common.DateStartEndContainerViewController', {
    extend: 'BaseViewController',
    alias: 'controller.DateStartEndContainerViewController',

    config: {
        viewId: 'DateStartEndContainer'
    },

    dateValid: function() {
        var me = this,
            refs = me.getReferences(),
            strdt = refs.strdt.getValue(),
            edt = refs.edt.getValue(),
            errMsg = '';

        if (!strdt || !edt) {
            errMsg = '시작일자와 종료일자를 올바르게 입력해주세요.';
        } else if (strdt.getTime() > edt.getTime()) {
            errMsg= '시작일이 종료일보다 클 수 없습니다.';
        }

        return errMsg;
    }

});